module.exports = async ({ require, assert }) => {
  const axios = require('./lib/axios.js').default;
  const zlib = require('zlib');
  const { PassThrough } = require('stream');
  const { EventEmitter } = require('events');
  const fetchWith = (encoding, body, extra) => {
    const transport = { request(options, onResponse) {
      const req = new EventEmitter();
      req.destroyed = false;
      req.setTimeout = () => req;
      req.destroy = () => { req.destroyed = true; return req; };
      req.write = () => true;
      req.end = () => {
        const res = new PassThrough();
        res.statusCode = 200; res.statusMessage = 'OK';
        res.headers = { 'content-type': 'text/plain', 'content-encoding': encoding };
        setImmediate(() => { onResponse(res); res.end(body); });
      };
      return req;
    } };
    return axios.get('http://qb.invalid/', Object.assign({ adapter: 'http', transport, responseType: 'text', timeout: 0 }, extra));
  };
  const body = zlib.gzipSync(Buffer.from('str'));
  for (const enc of ['GZIP', 'Gzip', 'GZip']) {
    const res = await fetchWith(enc, body);
    assert.strictEqual(res.data, 'str', `Content-Encoding ${enc}: body was not decompressed`);
  }
};

module.exports = async ({ require, assert }) => {
  const axios = require('./lib/axios.js').default;
  const zlib = require('zlib');
  const { PassThrough } = require('stream');
  const { EventEmitter } = require('events');
  const fetchWith = (encoding, body, extra) => {
    const transport = { request(options, onResponse) {
      const req = new EventEmitter();
      req.destroyed = false;
      req.setTimeout = () => req;
      req.destroy = () => { req.destroyed = true; return req; };
      req.write = () => true;
      req.end = () => {
        const res = new PassThrough();
        res.statusCode = 200; res.statusMessage = 'OK';
        res.headers = { 'content-type': 'text/plain', 'content-encoding': encoding };
        setImmediate(() => { onResponse(res); res.end(body); });
      };
      return req;
    } };
    return axios.get('http://qb.invalid/', Object.assign({ adapter: 'http', transport, responseType: 'text', timeout: 0 }, extra));
  };
  const text = 'qb mixed-case encoding body';
  const src = Buffer.from(text);
  const cases = [
    ['DEFLATE', zlib.deflateSync(src)],
    ['DEFLATE', zlib.deflateRawSync(src)],
    ['X-GZIP', zlib.gzipSync(src)],
    ['COMPRESS', zlib.gzipSync(src)],
  ];
  if (typeof zlib.createBrotliDecompress === 'function') cases.push(['BR', zlib.brotliCompressSync(src)]);
  for (const [enc, body] of cases) {
    const res = await fetchWith(enc, body);
    assert.strictEqual(res.data, text, `Content-Encoding ${enc}: body was not decompressed`);
  }
};

module.exports = async ({ require, assert }) => {
  const axios = require('./lib/axios.js').default;
  const zlib = require('zlib');
  const { PassThrough } = require('stream');
  const { EventEmitter } = require('events');
  const fetchWith = (encoding, body, extra) => {
    const transport = { request(options, onResponse) {
      const req = new EventEmitter();
      req.destroyed = false;
      req.setTimeout = () => req;
      req.destroy = () => { req.destroyed = true; return req; };
      req.write = () => true;
      req.end = () => {
        const res = new PassThrough();
        res.statusCode = 200; res.statusMessage = 'OK';
        res.headers = { 'content-type': 'text/plain', 'content-encoding': encoding };
        setImmediate(() => { onResponse(res); res.end(body); });
      };
      return req;
    } };
    return axios.get('http://qb.invalid/', Object.assign({ adapter: 'http', transport, responseType: 'text', timeout: 0 }, extra));
  };
  const body = zlib.gzipSync(Buffer.from('str'));
  const lower = await fetchWith('gzip', body);
  assert.strictEqual(lower.headers['content-encoding'], undefined, 'baseline: lowercase gzip header should be removed');
  const res = await fetchWith('GZIP', body);
  assert.strictEqual(res.data, 'str', 'Content-Encoding GZIP: body was not decompressed');
  assert.strictEqual(res.headers['content-encoding'], undefined, 'content-encoding header still present after decompressing GZIP');
};
